
import type { ReturnActorInput } from './ReturnActorInput.js';

export type ReturnInspectionLineItemInput = { /** RFC3339 timestamp. Format: date-time. */ "acceptance_decided_at"?: string | globalThis.Date; "acceptance_decided_by"?: ReturnActorInput; "acceptance_decision_reason"?: "inspection_result" | "return_policy" | "manual_review" | "other"; "acceptance_decision_reason_message"?: string; "acceptance_status": "accepted" | "rejected" | "review_required"; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "available_disposition_quantity": string; "condition": "new" | "unopened" | "opened" | "used" | "damaged" | "defective" | "incomplete" | "unknown"; "finding_codes": Array<"matches_expected_item" | "wrong_item" | "damaged" | "defective" | "used" | "missing_parts" | "empty_package" | "counterfeit_suspected" | "other">; "internal_note"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quantity": string; "return_inspection_id": string; "return_inspection_line_item_id": string; "return_line_item_id"?: string; "return_receipt_line_item_id": string; "supported_actions": Array<string>; };
